import{_ as e}from"./chunks/Lily58L-schematic.D7MvmkJl.js";import{_ as a,c as r,o as i,ae as d}from"./chunks/framework.DI6M9D4h.js";const l="/assets/Lily58L-pcb-2.D7FDhUsm.png",o="/assets/Lily58L-pcb-1.ki7PQ_wD.png",y=JSON.parse('{"title":"Lily58L","description":"","frontmatter":{},"headers":[],"relativePath":"build-guides/lily58l/README.md","filePath":"build-guides/lily58l/README.md","lastUpdated":1754309277000}'),s={name:"build-guides/lily58l/README.md"};function n(c,t,h,p,m,b){return i(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="lily58l" tabindex="-1">Lily58L <a class="header-anchor" href="#lily58l" aria-label="Permalink to &quot;Lily58L&quot;">​</a></h1><p><a href="https://github.com/firstcontributions/first-contributions" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/PRs-welcome-brightgreen.svg?style=flat-square" alt="PRs Welcome" loading="lazy"></a><a href="https://discord.gg/frjFXZB" title="Redirect to Keycapsss Discord" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/548530462419582996?style=flat-square&amp;logo=discord&amp;logoColor=white" alt="Discord" loading="lazy"></a><a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/License-CC%20BY--NC--SA%204.0-lightgrey.svg?style=flat-square" alt="License: CC BY-NC-SA 4.0" loading="lazy"></a></p><p>Lily58L is 6×4+4keys column-staggered split keyboard.</p><p>It is a modified version of the Lily58 Pro pcb from <a href="https://github.com/kata0510" target="_blank" rel="noreferrer">kata0510</a> and has the the following additional features.</p><ul><li>One rotary encoder support on each side (optional)</li><li>Optional Pimoroni Trackball (on master side)</li><li>Underglow with WS2812 (5050) RGB LED&#39;s (6 per side)</li><li>Per switch RGB LED with SK6812 Mini-E led (with legs, easy to solder)</li></ul><h2 id="build-guide" tabindex="-1"><a href="./buildguide_en.html">Build-Guide</a> <a class="header-anchor" href="#build-guide" aria-label="Permalink to &quot;[Build-Guide](buildguide_en.md)&quot;">​</a></h2><p><strong>Hardware available at <a href="https://keycapsss.com/keyboard-parts/pcbs/71/lily58l-split-keyboard-pcb" target="_blank" rel="noreferrer">keycapsss.com</a></strong></p><p><img src="'+l+'" alt="Lily58L PCB" loading="lazy"><img src="'+o+`" alt="Lily58L PCB" loading="lazy"></p><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><h3 id="rev1-3" tabindex="-1">Rev1.3 <a class="header-anchor" href="#rev1-3" aria-label="Permalink to &quot;Rev1.3&quot;">​</a></h3><ul><li>Change underglow footprint to WS2812 (5050) (easier to solder)</li><li>Add footprint for optional <a href="https://keycapsss.com/keyboard-parts/parts/157/pimoroni-trackball-breakout-i2c" target="_blank" rel="noreferrer">Pimoroni Trackball Module</a> (most inner position)</li><li>Improve silkscreen</li></ul><h3 id="rev1" tabindex="-1">REV1 <a class="header-anchor" href="#rev1" aria-label="Permalink to &quot;REV1&quot;">​</a></h3><ul><li>Add per switch RGB LED&#39;s (SK6812 Mini-E)</li><li>Add underglow RGB LED&#39;s (SK6812 Mini)</li><li>Add footprint for an optional rotary encoder</li></ul><h2 id="parts" tabindex="-1">Parts <a class="header-anchor" href="#parts" aria-label="Permalink to &quot;Parts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part name</th><th>Quantity</th><th>Remarks</th><th>Photo</th></tr></thead><tbody><tr><td>Lily58L PCB</td><td>2 pcs</td><td></td><td></td></tr><tr><td>Lily58L case</td><td>1 set</td><td>2 solid panels, 2 with holes for switches</td><td></td></tr><tr><td><a href="https://keycapsss.com/keyboard-parts/parts/79/arduino-pro-micro-atmega32u4-controller" target="_blank" rel="noreferrer">Pro Micro</a>, <a href="https://keycapsss.com/keyboard-parts/mcu-controller/141/puchi-c-pro-micro-replacement-with-usb-c-and-atmega32u4" target="_blank" rel="noreferrer">Puchi-C</a> or Elite-C</td><td>2 pcs (a mix is possible)</td><td>Optionally, use <a href="https://keycapsss.com/keyboard-parts/parts/100/single-row-socket-headers-pins-mill-max-series-315" target="_blank" rel="noreferrer">Mill-Max Single Row Socket Headers</a>, to make it hot-swappable.</td><td></td></tr><tr><td>Key switch (MX)</td><td>58 pcs</td><td></td><td></td></tr><tr><td><a href="https://keycapsss.com/keyboard-parts/parts/49/kailh-hot-swap-pcb-sockets-10-pcs" target="_blank" rel="noreferrer">Kailh switch socket</a></td><td>58 pcs</td><td></td><td></td></tr><tr><td>Diodes 1N4148W (SMD)</td><td>58 pcs</td><td></td><td></td></tr><tr><td>TRRS jack</td><td>2 pcs</td><td></td><td></td></tr><tr><td>Tactile switch</td><td>2 pcs</td><td>Reset switch</td><td></td></tr><tr><td>TRRS cable</td><td>1 cable</td><td>Must be a 4-pole cable</td><td></td></tr><tr><td>Key caps</td><td>58 pcs</td><td>1.5U caps, can also be 1U</td><td></td></tr><tr><td>Micro USB or USB-C cable</td><td>1 pcs</td><td>Dependent what you use on the master half.</td><td></td></tr></tbody></table><h3 id="optionally" tabindex="-1">Optionally <a class="header-anchor" href="#optionally" aria-label="Permalink to &quot;Optionally&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Part name</th><th>Quantity</th><th>Remarks</th><th>Photo</th></tr></thead><tbody><tr><td><a href="https://keycapsss.com/keyboard-parts/parts/80/ssd1306-oled-lcd-display-0.91-inch-128x32-i2c-white" target="_blank" rel="noreferrer">OLED module</a></td><td>2 pcs</td><td>It is possible to use only one display</td><td></td></tr><tr><td>WS2812 (5050)</td><td>12 pcs</td><td>RGB LED&#39;s for underglow</td><td></td></tr><tr><td>SK6812 Mini-E</td><td>58 pcs</td><td>RGB LED&#39;s for keycap backlight <strong>(underglow LED&#39;s must be soldered, because they are connected in series)</strong></td><td></td></tr></tbody></table><h2 id="firmware" tabindex="-1">Firmware <a class="header-anchor" href="#firmware" aria-label="Permalink to &quot;Firmware&quot;">​</a></h2><p>Clone/download the QMK firmware and execute the following in the <a href="https://github.com/qmk/qmk_firmware" target="_blank" rel="noreferrer">qmk_firmware</a> directory to write the default Lily58L keymap</p><pre><code>make lily58/light:lily58l:avrdude
</code></pre><p>When <strong><code>Detecting USB port, reset your controller now...</code></strong> is displayed, press the reset button on the keyboard to start writing. Each half of the keyboard must be programmed separately using this approach.</p><p>If you&#39;re using DFU bootloader (in case of the elite c), replace the &#39;avrdude&#39; with &#39;dfu&#39;</p><h2 id="schematic" tabindex="-1">Schematic <a class="header-anchor" href="#schematic" aria-label="Permalink to &quot;Schematic&quot;">​</a></h2><p><a href="img/Lily58L-schematic.png?raw=true"><img src="`+e+'" alt="Lily58L schematic" loading="lazy"></a></p>',24)])])}const f=a(s,[["render",n]]);export{y as __pageData,f as default};
